  if (k >= prm.nb) { return; }
  let bd = binds[k];
  let a = ld(bd.t0); let b = ld(bd.t1); let c = ld(bd.t2);
  let base = a * bd.w0 + b * bd.w1 + c * bd.w2;
  var n = cross(b - a, c - a);
